string[] commits = ["fix: handle null", "feat(api): add filter", "refactor: split class", "docs: update readme"];
var (major, minor, patch) = (1, 2, 3);
var level = 0; // 0 none, 1 patch, 2 minor, 3 major
foreach (var c in commits)
{
    var header = c.Split(':')[0];
    var l = header.EndsWith('!') ? 3 : header.StartsWith("feat") ? 2 : header.StartsWith("fix") ? 1 : 0;
    level = Math.Max(level, l);
}
if (level == 3) (major, minor, patch) = (major + 1, 0, 0);
else if (level == 2) (minor, patch) = (minor + 1, 0);
else if (level == 1) patch++;
Console.WriteLine($"{major}.{minor}.{patch}");

int first = 1, last = 10_000, firstBad = 6_000;
int tests = 0;
int good = first, bad = last;
while (bad - good > 1)
{
    int mid = (good + bad) / 2;
    tests++;
    if (mid >= firstBad) bad = mid; else good = mid;
}
Console.WriteLine($"{bad} {tests}");

static string Verdict(int code) => code switch
{
    0 => "good",
    125 => "skip",
    >= 1 and <= 127 => "bad",
    _ => "abort"
};
foreach (var code in new[] { 0, 1, 2, 125, 127 })
    Console.WriteLine($"{code}: {Verdict(code)}");

