using Microsoft.Extensions.Logging;

var factory = LoggerFactory.Create(b => b.AddProvider(new KeyProvider()));
var logger = factory.CreateLogger("demo");
int orderId = 4729, customerId = 7;

logger.LogInformation($"Xu ly don {orderId} cho khach {customerId}");
logger.LogInformation("Xu ly don {OrderId} cho khach {CustomerId}", orderId, customerId);

class KeyProvider : ILoggerProvider
{
    public ILogger CreateLogger(string name) => new L();
    public void Dispose() { }
    class L : ILogger
    {
        public IDisposable? BeginScope<T>(T state) where T : notnull => null;
        public bool IsEnabled(LogLevel l) => true;
        public void Log<T>(LogLevel l, EventId id, T state, Exception? ex, Func<T, Exception?, string> f)
        {
            var keys = ((IReadOnlyList<KeyValuePair<string, object?>>)state!).Select(kv => kv.Key);
            Console.WriteLine(string.Join(",", keys));
        }
    }
}
